const bannerCategory = "";
const bannerSubCategory = "";
const bannerLanguage = "en";
const bannerDevice = "desktop";
const bannerCountry = "om";
const bannerCity = "";
const bannerNhood = [];
const bannerSelectedFilters = {"cps":{},"allData":{}};
googletag.cmd.push(function () {
  if (bannerCategory) googletag.pubads().setTargeting("category", bannerCategory);
  if (bannerSubCategory) googletag.pubads().setTargeting("SubCategory", bannerSubCategory);
  if (bannerLanguage) googletag.pubads().setTargeting("language", bannerLanguage);
  if (bannerDevice) googletag.pubads().setTargeting("device", bannerDevice);
  if (bannerCountry) googletag.pubads().setTargeting("country", bannerCountry);
  if (bannerCity) googletag.pubads().setTargeting("city", bannerCity);

  if (Array.isArray(bannerNhood)) {
    bannerNhood.forEach(neighborhood => {
      googletag.pubads().setTargeting("neighborhood", neighborhood);
    });
  }

  if (bannerSelectedFilters.cps && typeof bannerSelectedFilters === "object") {
    Object.entries(bannerSelectedFilters.cps).forEach(([filterKey, filterValues]) => {
        (Array.isArray(filterValues) ? filterValues : [filterValues]).forEach(value => {
        googletag.pubads().setTargeting(filterKey, value);
      });
    });
  }
});

