 function techLogger(level, label, payload) {
      var msg = payload ? JSON.stringify(payload) : "";
      var category = label;
      var data = { level, msg, category };
      fetch("/v2.1/logging/tech-log" , {
       method: "POST",
       body: JSON.stringify(data),
       headers: {
         "content-type": "application/json",
         "source": window.screen > 800 ? "desktop" : "mobile"
       },
      })
       .then((res) => res.text())
       .then(console.log);
}

if ('serviceWorker' in navigator) {
  navigator.serviceWorker.getRegistrations()
    .then(registrations => {
      if (!registrations.length) return;

      registrations.forEach(registration => {
        var scriptURL = (registration.active && registration.active.scriptURL) || (registration.installing && registration.installing.scriptURL) || '';
        if (scriptURL.indexOf('firebase-messaging-sw') !== -1) return;

        console.log('Unregister service worker:', registration);
        techLogger("warning", "Service Worker - Unregister Attempt");

        registration.unregister()
          .then(() => {
            console.log('Service worker unregistered successfully');
            techLogger("warning", "Service Worker - Unregister success");
          })
          .catch(error => {
            console.error('Service worker unregister failed:', error);
            techLogger("warning", "Service Worker - Unregister failed");
          });
      });
    })
    .catch(error => {
      console.error('Error fetching service worker registrations:', error);
    });
}
